<#
.SYNOPSIS
    hy — Vibe Coding 工作流插件 一键安装器（自包含，全局安装）
.DESCRIPTION
    解压内置插件并全局安装（优先 claude plugin CLI，回退直接复制到 ~/.claude/）
.EXAMPLE
    .\install.ps1
#>
param()

$ErrorActionPreference = "Stop"
# node（claude CLI）输出 UTF-8，统一控制台编码避免中文/符号乱码（PS 5.1 默认 GBK）
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }
Write-Host "[i] hy 插件安装器 v1.0" -ForegroundColor Cyan
Write-Host ""

# ── 1. 解压插件到 ~/.hy/plugin ──
$PluginDir = Join-Path (Join-Path $HOME ".hy") "plugin"
New-Item -ItemType Directory -Path $PluginDir -Force | Out-Null
Write-Host "[i] 解压插件到 $PluginDir ..." -ForegroundColor Cyan

$b64 = ''
$bytes = [Convert]::FromBase64String($b64)
$tempTar = Join-Path ([System.IO.Path]::GetTempPath()) "hcoder_$([System.IO.Path]::GetRandomFileName()).tar.gz"
[System.IO.File]::WriteAllBytes($tempTar, $bytes)

$oldLoc = Get-Location
Set-Location $PluginDir
# 优先使用 Windows 自带 tar.exe（Git Bash 的 GNU tar 不认 Windows 路径）
$TarExe = if (Test-Path (Join-Path $env:SystemRoot "System32\tar.exe")) {
    Join-Path $env:SystemRoot "System32\tar.exe"
} else { "tar" }
& $TarExe -xzf $tempTar
$tarOk = ($LASTEXITCODE -eq 0)
Set-Location $oldLoc
Remove-Item -Force $tempTar -ErrorAction SilentlyContinue
if (-not $tarOk) { Write-Host "[!] 解压失败" -ForegroundColor Red; exit 1 }

# ── 2. 安装：优先官方 CLI，回退直接复制 ──
# claude CLI 在 Windows 上需要 git-bash（自动探测并设置）
function Ensure-GitBash {
    if ($env:CLAUDE_CODE_GIT_BASH_PATH -and (Test-Path $env:CLAUDE_CODE_GIT_BASH_PATH)) { return $true }
    foreach ($c in @("C:\Program Files\Git\bin\bash.exe", "C:\Program Files\Git\usr\bin\bash.exe", "D:\Program Files\Git\bin\bash.exe", "D:\Program Files\Git\usr\bin\bash.exe", "$env:LOCALAPPDATA\Programs\Git\bin\bash.exe")) {
        if (Test-Path $c) { $env:CLAUDE_CODE_GIT_BASH_PATH = $c; return $true }
    }
    return $false
}

$cliInstalled = $false
$cli = Get-Command claude -ErrorAction SilentlyContinue
if ($cli) {
    Write-Host "[i] 使用 claude plugin CLI 安装..." -ForegroundColor Cyan
    $null = Ensure-GitBash
    $prevEAP = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    $null = & claude --version 2>&1
    if ($LASTEXITCODE -eq 0) {
        Set-Location (Join-Path $HOME ".hy")
        & claude plugin marketplace add "./plugin" 2>&1 | Out-Null
        $PluginListOut = (& claude plugin list 2>&1 | Out-String)
        if ($PluginListOut -match "\bhy\b") {
            $NewVer = (Get-Content (Join-Path $PluginDir ".claude-plugin/plugin.json") -Raw | ConvertFrom-Json).version
            $OldVer = $null
            if ($PluginListOut -match "Version:\s*([0-9]+\.[0-9]+\.[0-9]+)") { $OldVer = $Matches[1] }
            if ($NewVer -and $OldVer -and $NewVer -ne $OldVer) {
                Write-Host "[i] hy v$OldVer → v$NewVer：先卸载旧版本再安装（避免合并残留）..." -ForegroundColor Cyan
                & claude plugin uninstall hy -s user -y 2>&1 | Out-Null
                & claude plugin install hy -s user 2>&1 | Out-Null
                $cliInstalled = ($LASTEXITCODE -eq 0)
            } else {
                $cliInstalled = $true
                Write-Host "[i] hy 插件已安装且版本一致（v$NewVer），跳过 install" -ForegroundColor Cyan
            }
        } else {
            & claude plugin install hy -s user 2>&1 | Out-Null
            $cliInstalled = ($LASTEXITCODE -eq 0)
        }
        Set-Location $oldLoc
        if ($cliInstalled -and ((& claude plugin list 2>&1 | Out-String) -match "\bhy\b")) {
            Write-Host "[OK] hy 插件已通过 CLI 全局安装" -ForegroundColor Green
        } else {
            Write-Host "[!] CLI 安装失败或未验证通过，回退直接复制模式..." -ForegroundColor Yellow
            $cliInstalled = $false
        }
    } else {
        Write-Host "[!] claude CLI 不可用（git-bash 依赖未满足），回退直接复制模式..." -ForegroundColor Yellow
    }
    $ErrorActionPreference = $prevEAP
} else {
    Write-Host "[i] 未找到 claude CLI，直接复制到 ~/.claude/ ..." -ForegroundColor Cyan
}

if (-not $cliInstalled) {
    $UserClaude = Join-Path $HOME ".claude"
    $SkillsTarget = Join-Path $UserClaude "skills"
    $CommandsTarget = Join-Path $UserClaude "commands"
    $AgentsTarget = Join-Path $UserClaude "agents"
    $ScriptsTarget = Join-Path (Join-Path $UserClaude "scripts") "hy"
    New-Item -ItemType Directory -Path $SkillsTarget -Force | Out-Null
    New-Item -ItemType Directory -Path $CommandsTarget -Force | Out-Null
    New-Item -ItemType Directory -Path $AgentsTarget -Force | Out-Null
    New-Item -ItemType Directory -Path $ScriptsTarget -Force | Out-Null
    Get-ChildItem (Join-Path $PluginDir "skills") -Directory | ForEach-Object {
        $dest = Join-Path $SkillsTarget $_.Name
        if (Test-Path $dest) { Remove-Item -Recurse -Force $dest }
        Copy-Item -Recurse $_.FullName $dest
    }
    $HyCommandsTarget = Join-Path $CommandsTarget "hy"
    New-Item -ItemType Directory -Path $HyCommandsTarget -Force | Out-Null
    Get-ChildItem (Join-Path $PluginDir "commands") -Filter *.md | ForEach-Object {
        Copy-Item $_.FullName (Join-Path $HyCommandsTarget $_.Name) -Force
    }
    Get-ChildItem (Join-Path $PluginDir "agents") -Filter *.md | ForEach-Object {
        Copy-Item $_.FullName (Join-Path $AgentsTarget $_.Name) -Force
    }
    $ReferenceTarget = Join-Path $UserClaude "reference"
    New-Item -ItemType Directory -Path $ReferenceTarget -Force | Out-Null
    Get-ChildItem (Join-Path $PluginDir "reference") | ForEach-Object {
        $dest = Join-Path $ReferenceTarget $_.Name
        if (Test-Path $dest) { Remove-Item -Recurse -Force $dest }
        Copy-Item -Recurse $_.FullName $dest
    }
    Get-ChildItem (Join-Path (Join-Path $PluginDir "hooks") "scripts") -Filter *.js | ForEach-Object {
        Copy-Item $_.FullName (Join-Path $ScriptsTarget $_.Name) -Force
    }

    $ScriptsPath = $ScriptsTarget -replace "\\", "/"
    $HooksConfig = Get-Content (Join-Path (Join-Path $PluginDir "hooks") "hooks.json") -Raw | ConvertFrom-Json
    $HooksConfig.hooks.PostToolUse[0].hooks[0].command = "node $ScriptsPath/style-gate.js"
    $HooksConfig.hooks.PreToolUse[0].hooks[0].command = "node $ScriptsPath/commit-gate.js"

    $SettingsTarget = Join-Path $UserClaude "settings.json"
    $PluginSettings = Get-Content (Join-Path $PluginDir "settings.json") -Raw | ConvertFrom-Json
    if (Test-Path $SettingsTarget) {
        $Existing = Get-Content $SettingsTarget -Raw | ConvertFrom-Json
        if (-not $Existing.PSObject.Properties.Name -contains "hooks") {
            $Existing | Add-Member -NotePropertyName hooks -NotePropertyValue $HooksConfig.hooks
        } else {
            foreach ($EventName in @("PostToolUse", "PreToolUse")) {
                $NewEntry = $HooksConfig.hooks.$EventName[0]
                $Dup = $false
                foreach ($Entry in $Existing.hooks.$EventName) {
                    foreach ($H in $Entry.hooks) {
                        if ($H.command -like "*$($NewEntry.hooks[0].command.Split('/')[-1])*") { $Dup = $true }
                    }
                }
                if (-not $Dup) { $Existing.hooks.$EventName += $NewEntry }
            }
        }
        if ($PluginSettings.env) {
            if (-not $Existing.PSObject.Properties.Name -contains "env") {
                $Existing | Add-Member -NotePropertyName env -NotePropertyValue $PluginSettings.env
            } else {
                foreach ($K in $PluginSettings.env.PSObject.Properties.Name) {
                    if (-not $Existing.env.PSObject.Properties.Name -contains $K) {
                        $Existing.env | Add-Member -NotePropertyName $K -NotePropertyValue $PluginSettings.env.$K
                    }
                }
            }
        }
        $Existing | ConvertTo-Json -Depth 10 | Set-Content $SettingsTarget -Encoding UTF8
    } else {
        $NewSettings = [PSCustomObject]@{ hooks = $HooksConfig.hooks; env = $PluginSettings.env }
        $NewSettings | ConvertTo-Json -Depth 10 | Set-Content $SettingsTarget -Encoding UTF8
    }
    Write-Host "[OK] hy 插件已复制到 ~/.claude/（hooks + Agent Teams 已注册）" -ForegroundColor Green
    Write-Host "[!] 注意：直接复制模式不安装 MCP（hy-db-tools 等），如需数据库查询请改用 claude CLI 安装" -ForegroundColor Yellow
}

# ── 3. 初始化 hy-db-tools 配置（~/.hy/db-mcp/config.json）──
$DbMcpDir = Join-Path (Join-Path $HOME ".hy") "db-mcp"
$DbMcpCfg = Join-Path $DbMcpDir "config.json"
if (-not (Test-Path $DbMcpCfg)) {
    New-Item -ItemType Directory -Path $DbMcpDir -Force | Out-Null
    $cfgContent = '{"apiUrl": "http://10.1.34.16:30023/api/code-gen", "token": "Fn_zBLISZYEjTpLXH_jvXNCSPkMssxgLZX__"}'
    [System.IO.File]::WriteAllText($DbMcpCfg, $cfgContent, (New-Object System.Text.UTF8Encoding($false)))
    Write-Host "[i] 已创建 hy-db-tools 配置文件 $DbMcpCfg（含默认 Token）" -ForegroundColor Cyan
}
$DbCfg = Get-Content $DbMcpCfg -Raw -ErrorAction SilentlyContinue
if ($DbCfg -match '"token":\s*""') {
    Write-Host "[i] 检测到 Token 为空（旧版本安装），可运行 node `"$PluginDir\mcp\hy-db-tools\server.js`" --set-token <token> 写入测试环境接口 Token（默认值：Fn_zBLISZYEjTpLXH_jvXNCSPkMssxgLZX__）" -ForegroundColor Yellow
}

Write-Host ""
Write-Host "[OK] hy 插件安装完成！" -ForegroundColor Green
Write-Host ""
Write-Host "[i] 所有项目可用：" -ForegroundColor Cyan
Write-Host "  ① 流程    /hy:run（自动路由）· /hy:run-stats /hy:run-crud /hy:run-screen /hy:run-all（指定流程）"
Write-Host "  ② 专家    @hy:product / design / lead / backend / frontend / ui / db / test（直接引用）"
Write-Host "  ③ 门禁    自动生效（风格红线 · git 提交交人工）"
Write-Host "  ④ 版本    /hy:version（查看版本）· /hy:help（帮助）· /hy:update（检查更新）"
Write-Host ""
Write-Host "[i] 如果 Claude Code 已打开，执行 /reload-plugins 或重启生效。" -ForegroundColor Cyan
